import fasttext
from pathlib import Path

from scripts.preprocessing.predict_language import predict as predict_language
from scripts.preprocessing.harmful_content_detector import classify_nsfw, classify_hate
from scripts.preprocessing.extract_text import extract_text_from_html
from pathlib import Path
from fastwarc.warc import ArchiveIterator, WarcRecordType
from scripts.preprocessing.gopher_quality_filters import is_high_quality

from pathlib import Path
import numpy as np

def get_valid_record(iter: ArchiveIterator):
    max_tries = 100
    for i in range(max_tries):
        record = next(iter)
        body_content = record.reader.read()
        text = extract_text_from_html(body_content, strict=False)
        if len(text) == 0:
            continue
        model_guess, confidence = predict_language(text, disable_warning=True)
        if model_guess != "en" or confidence < 0.7:
            continue
        return text
    else:
        raise ValueError("None of the next 100 records are in english")

def create_training_data(out_file_path, in_file_path, wiki_warcs):
    with open(out_file_path, "w") as fo:
        with open(in_file_path, "rb") as fi1:
            ai = ArchiveIterator(fi1, record_types=WarcRecordType.response)
            num_cc = 0
            while num_cc < 1000:
                try:
                    text = get_valid_record(ai).replace("\n", " ")
                    c1 = classify_hate(text)[0] == "toxic"
                    c2 = classify_nsfw(text)[0] == "nsfw"
                    c3 = not is_high_quality(text)
                    if c1 or c2 or c3:
                        continue
                    fo.write("__label__cc "+ text+"\n")
                    num_cc += 1
                except StopIteration:
                    fo.flush()
                    break
        for i, file in enumerate(wiki_warcs):
            print("processing file ", i)
            with open(file, "rb") as fi2:
                ai = ArchiveIterator(fi2, record_types=WarcRecordType.response)
                while True:
                    try:
                        text = get_valid_record(ai).replace("\n", " ")
                        c1 = classify_hate(text)[0] == "toxic"
                        c2 = classify_nsfw(text)[0] == "nsfw"
                        c3 = not is_high_quality(text)
                        if c1 or c2 or c3:
                            continue
                        fo.write("__label__wiki " + text + "\n")
                    except StopIteration:
                        break

def create_classifier(data_file_path, model_path):
    model = fasttext.train_supervised(data_file_path, epoch=1000)
    model.save_model(model_path)

classifier = fasttext.load_model("./local-shared-data/classifiers/joes_model.bin")

def predict_quality(txt, score=False):
    txt = txt.replace("\n", " ")
    res = classifier.predict(txt)
    sc = res[1][0]
    label = res[0][0][9:]
    if score:
        if label == "wiki":
            return np.clip(sc, 0, 1)
        return np.clip(sc, 0, 1)
    return (label, sc)
    
if __name__ == "__main__":
    out_file_path = Path("./local-shared-data/wiki/classifier.txt")
    in_file_path = Path("./local-shared-data/CC/example.warc")
    wiki_warcs = Path("./local-shared-data/wiki/positive_warcs").glob("*.warc")
    model_path = "./local-shared-data/classifiers/joes_model.bin"
    create_training_data(out_file_path, in_file_path, wiki_warcs)
    create_classifier(str(out_file_path), model_path)
    
    model = fasttext.load_model(model_path)
